"""Weekly timesheet lines, one per worker."""

from hourglass.schedule import worker_minutes
from hourglass.errors import ProjectError
from collections import Counter


def _check(rows):
    if not rows:
        raise ProjectError("no shifts to total")
    for shift in rows:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker name")


def _totals(rows):
    counts = Counter(shift.worker for shift in rows)
    minutes = worker_minutes(rows)
    return [(who, counts[who], minutes[who])
            for who in counts]


def _line(name, count, minutes):
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"


# ---
def timesheet_lines(shifts):
    """One line per worker, most hours first."""
    rows = list(shifts)
    _check(rows)
    ordered = sorted(
        _totals(rows), key=lambda item: (-item[2], item[0])
    )
    return [_line(*item) for item in ordered]

