import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            make_shift("Ana", 9, 10),
            make_shift("Bo", 9, 12),
            make_shift("Ana", 13, 14)
        ])
        self.assertEqual(lines, [
            "Bo: 1 shifts, 3.0 hours",
            "Ana: 2 shifts, 2.0 hours"
        ])

    def test_one_decimal(self):
        shift = Shift("Ana", "tue", Span(540, 625))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Ana: 1 shifts, 1.4 hours"]
        )

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([make_shift("  ", 9, 10)])
